document.body.classList.add('physical-operation');
function update(){
 const {unit:u,job}=window.fmcGame.controlState(),busy=u.phase!=='ready'||!!u.fault||!!u.service;
 for(const span of document.querySelectorAll('#decision .unit-status span'))if(span.textContent.startsWith('Target aisle:'))span.textContent=job?'Assigned berth: '+(u.load?job.destination:job.source):'Waiting for the next assignment';
 const inspection=document.querySelector('#game-calculations[open] #calculation-content');if(inspection&&document.querySelector('#game-calculations[open]')&&!inspection.querySelector('#physical-run-note')){const note=document.createElement('p');note.id='physical-run-note';note.className='inspection-note';note.textContent='Synthetic warehouse model: shared synthetic vehicle dimensions; travel, handling and waiting determine actual results. Contract formulas are unchanged. Ten staging berths keep the workshop doorway clear. Routes reserve the vehicle and its manoeuvres. Continuous operation keeps queued engines off, replenishes dispatched stock and renews contract months. Recovery preserves the original fault, pallet and job.';inspection.prepend(note);}
 if(inspection)for(const row of inspection.querySelectorAll('tr')){const key=row.cells[0]?.textContent,text=key==='One tile / pickup or placement'?'Physical paths / finite 7.7-second handling sequence':key==='Navigation'?'Calibrated lanes; full-vehicle and crew-access reservations; finite turns and gear changes.':null;if(text&&row.cells[1].textContent!==text)row.cells[1].textContent=text;}
 if(inspection)for(const paragraph of inspection.querySelectorAll('p')){if(paragraph.textContent.includes('A travel/handling cycle is a symbolic physical action'))paragraph.textContent='View, speed, pause and reduced motion affect presentation. Positions, finite turning, handling and space reservations govern each physical job. Operating exposure uses the existing scenario clock and formula.';if(paragraph.textContent.includes('There are no inventory lead times or industrial driving physics.'))paragraph.textContent='Fault rates remain editable before opening. Repairs retain carried loads; crews begin only after the vehicle stops, steering is centred and access is clear. Vehicle geometry is a shared synthetic profile; mass, friction and manufacturer load ratings are outside this model.';}
 const root=document.querySelector('#driving-controls');if(!root.children.length)return;
 if(!root.querySelector('#physical-auto')){const actions=document.createElement('div');actions.className='physical-drive-actions';actions.append(root.querySelector('[data-action="handle"]'));const automatic=document.createElement('button');automatic.id='physical-auto';automatic.dataset.action='control';automatic.textContent='Return to automatic';actions.append(automatic);root.append(actions);}
 const note=root.querySelector('span');if(note&&note.textContent!=='Safe waypoints: WASD / arrows. Handle assigned pallet: Space.')note.textContent='Safe waypoints: WASD / arrows. Handle assigned pallet: Space.';
 for(const button of root.querySelectorAll('[data-drive]')){const disabled=busy;if(button.disabled!==disabled)button.disabled=disabled;const label={up:'W North',left:'A West',down:'S South',right:'D East'}[button.dataset.drive];if(button.textContent!==label)button.textContent=label;}
 const handle=root.querySelector('[data-action="handle"]');if(handle){const disabled=busy||!u.job;if(handle.disabled!==disabled)handle.disabled=disabled;const text=(u.load?'Place assigned pallet':'Pick up assigned pallet')+' · Space';if(handle.textContent!==text)handle.textContent=text;}
}
const observer=new MutationObserver(update);observer.observe(document.querySelector('#live-state'),{childList:true});observer.observe(document.querySelector('#driving-controls'),{childList:true,subtree:true});observer.observe(document.querySelector('#calculation-content'),{childList:true});document.addEventListener('click',()=>queueMicrotask(update));document.addEventListener('change',()=>queueMicrotask(update));addEventListener('pagehide',()=>observer.disconnect());
